function go(page){if(['reception','leads','comments'].includes(page))page='customers/'+page;if(location.hash==='#'+page)render();else location.hash=page}
function toast(t){$('#toast').textContent=t.replace(/Mock|模拟|演示/gi,'');$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',2800)}
function modal(title,body){$('#dialog').classList.remove('service-editor');$('#dialog').innerHTML=`<div class="modal-head"><h2>${title}</h2>${B(I('close'),'close','icon-button','aria-label="关闭"')}</div>${body}`;$('#dialog').showModal();paginateLists();polishVisible()}
