function dueToday(value){if(!value)return false;if(/今天|今日|逾期/.test(value))return true;const now=new Date(),m=value.match(/(?:(\d{4})-)?(\d{1,2})[-月](\d{1,2})/);return !!m&&new Date(Number(m[1]||now.getFullYear()),Number(m[2])-1,Number(m[3]))<=new Date(now.getFullYear(),now.getMonth(),now.getDate())}
function homePending(){const rows=[],add=(title,detail,label,action,id,priority)=>rows.push({title,detail,label,action,id,priority});
const alerts=inboxRecords.filter(q=>q.alert&&!S.manual[q.id]&&!q.waitingResponse);
alerts.forEach(q=>add('客户'+q.id+'等待接手',q.platform+' · '+q.reason,'接手沟通','home-conversation',q.id,'优先处理'));
clients.forEach(c=>{const origins=customerConversations(c);if(c.stage==='已关闭'||origins.some(q=>alerts.includes(q)||q.waitingResponse))return;if(c.stage==='待确认')add('客户'+c.id+'等待确认承接',c.service,'查看需求','home-client',c.id,'待你确认');else if(!c.taskDone&&c.next!=='—'&&dueToday(c.due))add('客户'+c.id+' · '+c.next,c.service+' · '+c.due,'去跟进','home-client',c.id,'到期跟进')});
tasks.forEach((t,i)=>{const missing=['抖音','小红书'].filter(p=>!versionStore[i+'-'+p]?.approved);if(t[2]==='待审核'&&missing.length)add(t[0],missing.join('、')+'版本待审核','审核内容','home-content',i,'专业审核');else if(['待观点','待定稿','待拍摄'].includes(t[2])||['创作中','脚本中'].includes(t[2])&&/补充|审核/.test(contentInfo(i).next))add(t[0],contentInfo(i).next,'处理内容','home-content',i,'需要你参与')});
commentInsights.filter(c=>c.intent==='高'&&c.fit&&serviceActive(c.service)&&!c.sent&&c.status!=='暂不触达').forEach(c=>add(c.user+'有咨询意向',c.platform+'评论 · '+c.reason,'确认回复','home-outreach',c.id,'触达确认'));
S.posts.forEach((p,i)=>{if(p.status==='发布失败'||p.status.includes('暂停')&&!rows.some(r=>r.title===p.title))add(p.title,p.platform+' · '+p.status,'处理异常','post-detail',i,'发布异常')});return rows}
function home(){const pending=homePending(),waiting=inboxRecords.filter(q=>q.waitingResponse).length,prepared=commentInsights.filter(c=>c.intent==='高'&&c.fit&&serviceActive(c.service)&&!c.sent&&c.status!=='暂不触达').length,producing=tasks.filter(t=>['创作中','脚本中','制作中','退回修改'].includes(t[2])).length,responded=inboxRecords.reduce((n,q)=>n+q.messages.filter(m=>m.who==='agent').length,0),questions=commentInsights.filter(c=>c.topic==='流程疑问');return `<div class="page-intro"><div><h2>把关键决定留给你</h2><p class="muted">${pending.length} 项需要处理 · 接待、内容与跟进统一汇总，处理后同步更新。</p></div>${B('交代新任务','assistant')}</div><div class="operations-layout"><section class="panel focus-tasks"><div class="panel-head"><h2>需要你处理</h2>${badge(pending.length+' 项')}</div>${pending.map(r=>`<div class="decision-row"><div class="decision-copy"><span class="muted">${esc(r.priority)}</span><h3>${esc(r.title)}</h3><p class="muted">${esc(r.detail)}</p></div>${B(r.label,r.action,r.priority==='优先处理'?'primary':'',`data-index="${esc(r.id)}"`)}</div>`).join('')||'<div class="empty">当前没有需要你处理的事项，可以查看工作进展。</div>'}</section><aside class="operations-side"><section class="panel"><div class="panel-head"><h2>Agent 工作进展</h2></div><div class="operation-progress"><strong>待确认的触达机会</strong><p>${prepared} 条高意向评论，已准备回复建议。</p>${B('查看评论洞察','home-comments','quiet')}</div><div class="operation-progress"><strong>内容制作队列</strong><p>${producing} 条内容处于起草、制作或修改阶段。</p>${A('查看内容进度','content')}</div><div class="operation-progress"><strong>接待记录</strong><p>已记录 ${responded} 条 Agent 回复；${waiting} 位客户等待回应。</p>${A('查看咨询接待','customers/reception')}</div></section><section class="panel"><div class="panel-head"><h2>今日运营建议</h2></div><p>${questions.length?'评论中有 '+questions.length+' 条流程疑问，建议补充一条咨询准备内容。':'先积累更多客户问题，再确定新的内容方向。'}</p><p class="muted">依据：当前评论中的“流程疑问”。目标是减少重复解释，帮助客户做好首次咨询准备。</p><div class="row wrap">${B('查看评论依据','home-comment-evidence','quiet')}${B('查看需求与策划','comment-market')}</div></section></aside></div>`}
