contentMeta[3].result={views:'24,360',consults:12,matched:4,appointments:2};contentMeta[11].result={views:'8,740',consults:7,matched:1,appointments:1};contentMeta[9].scheduled=true;
S.posts=[{title:tasks[0][0],platform:'抖音',status:'暂停：等待V2确认',at:'2026-11-19T10:00'},{title:tasks[9][0],platform:'抖音',status:'已排期',at:'2026-11-18T10:00'},...[[3,'2026-11-16T14:00'],[11,'2026-11-15T10:00']].map(([i,at])=>({title:tasks[i][0],platform:'小红书',status:'已发布',at}))];
S.posts.push({title:tasks[3][0],platform:'抖音',status:'已发布',at:'2026-11-16T16:00',version:1},{title:tasks[11][0],platform:'抖音',status:'发布失败',at:'2026-11-17T09:00',version:1,error:'模拟异常：上传超时，请重新安排发布'});
function contentInfo(i){return contentMeta[i]||{service:'婚前财产规划',goal:'推动咨询',source:'运营计划',audience:'有相关服务需求的人',point:'先整理客户问题与专业观点，再由达人确认。',next:'补充观点与素材',due:'待安排',format:'口播 / 图文',owner:'AI 起草 / 林律师确认'}}
function platformPost(i,platform){const rows=S.posts.filter(p=>p.title===tasks[i][0]&&p.platform===platform);return rows.find(p=>p.status!=='已发布')||rows.at(-1)}
function contentStage(i){const posts=S.posts.filter(p=>p.title===tasks[i][0]);const published=new Set(posts.filter(p=>p.status==='已发布').map(p=>p.platform));if(posts.some(p=>p.status.includes('暂停')))return posts.filter(p=>p.status.includes('暂停')).every(p=>versionStore[i+'-'+p.platform]?.approved)?'待排期':'待审核';if(posts.some(p=>p.status==='发布失败'))return '发布异常';if(['抖音','小红书'].some(p=>versionStore[i+'-'+p]?.approved===false)&&published.size)return '待审核';if(published.size===2)return '已发布';if(published.size)return '部分发布';if(posts.some(p=>p.status==='已排期'))return '已排期';if(versionStore[i+'-抖音']?.approved||versionStore[i+'-小红书']?.approved)return '待排期';return tasks[i][2]}
function contentViews(){return `<div class="tabs strategy-tabs content-view-tabs">${['内容列表','发布日历'].map(t=>B(t,'content-view', (S.contentView||'内容列表')===t?'active':'',`data-tab="${t}"`)).join('')}</div>`}
function publishingPanel(){const post=platformPost(S.task,S.platform),same=post?.status==='已发布'&&(post.version||1)===S.version;return `<section class="inline-publish"><div><h3>${esc(S.platform)} · 审核与发布</h3><p class="muted">${post?esc(post.status)+' · '+esc(post.at.replace('T',' ')):'尚未安排发布'}${post?.error?' · '+esc(post.error):''}</p><p class="muted">当前 V${S.version} ${S.approved?'已审核':'待审核'}${post?.status==='已发布'?'；已发布记录保留，不自动替换。':'；修改实质内容后，相关排期将暂停。'}</p></div><div class="row wrap">${post?.status==='已排期'?B('取消排期','cancel-schedule'):''}${S.approved&&!same?B(post?.status==='已排期'?'调整排期':post?.status==='发布失败'?'重新安排':'预约发布','schedule-open','primary')+B('立即发布','publish-now'):same?badge('当前版本已发布'):badge('审核后可发布','amber')}</div></section>`}
function openPublishForm(now=false){if(!S.approved)return toast('请先审核当前平台版本');S.publishMode=now?'now':'schedule';const post=platformPost(S.task,S.platform);formModal(now?'确认模拟发布':'预约发布',`<p><strong>${esc(tasks[S.task][0])}</strong></p><p class="muted">${esc(S.platform)} · V${S.version} · 已审核</p><div class="spacer"></div><input type="hidden" name="title" value="${esc(tasks[S.task][0])}"><input type="hidden" name="platform" value="${esc(S.platform)}">${now?'<p>确认后将当前平台版本标记为已发布。此操作仅更新模拟数据。</p>':field('发布时间','at',post?.at||'2026-11-20T10:00','datetime-local')}<p class="mock-note">Mock 演示，不向真实平台发送任何内容。</p>`,'schedule-form',now?'确认模拟发布':'保存排期')}
function contentList(){const rows=tasks.map((t,i)=>({t,i,m:contentInfo(i),stage:contentStage(i)})).filter(x=>(!S.contentFilter||S.contentFilter==='全部'||x.stage===S.contentFilter)&&(!S.contentService||S.contentService==='全部服务'||x.m.service===S.contentService)&&(!S.contentQuery||(x.t[0]+x.m.goal+x.m.source+x.m.audience).includes(S.contentQuery)));return `<div class="page-intro"><div><h2>我的内容</h2><p class="muted">从选题到发布，按内容目标与当前进度推进。</p></div>${B('从市场洞察找选题','topics')}</div><div class="content-overview"><span>内容总数 <strong>${tasks.length}</strong></span><span>待达人处理 <strong>${tasks.filter((_,i)=>['待审核','待观点','退回修改','待定稿'].includes(contentStage(i))).length}</strong></span><span>已排期 <strong>${tasks.filter((_,i)=>contentStage(i)==='已排期').length}</strong></span><span>已发布 <strong>${tasks.filter((_,i)=>contentStage(i)==='已发布').length}</strong></span></div><form id="content-search" class="library-toolbar"><input name="query" value="${esc(S.contentQuery||'')}" placeholder="搜索选题、目标或来源" aria-label="搜索内容"><button>搜索</button><select id="content-stage" aria-label="创作阶段">${['全部',...new Set(tasks.map((_,i)=>contentStage(i)))].map(t=>`<option value="${esc(t)}" ${S.contentFilter===t?'selected':''}>${t==='全部'?'全部阶段':t}</option>`).join('')}</select><select id="content-service" aria-label="关联服务">${['全部服务',...S.services].map(t=>`<option value="${esc(t)}" ${S.contentService===t?'selected':''}>${t}</option>`).join('')}</select>${B('重置','content-reset','quiet')}</form><div class="panel content-index content-rich"><table class="full-table"><thead><tr><th>内容与形式</th><th>服务 / 目标</th><th>来源</th><th>阶段</th><th>下一步 / 时间</th><th></th></tr></thead><tbody>${rows.map(({t,i,m,stage})=>`<tr><td><strong>${esc(t[0])}</strong><p class="muted">${esc(m.format)}</p></td><td>${esc(m.service)}<p class="muted">${esc(m.goal)}</p></td><td>${esc(m.source)}</td><td>${badge(stage,['待审核','退回修改'].includes(stage)?'amber':'')}</td><td>${esc(m.next)}<p class="muted">${m.result?'发布于':'计划'} ${esc(m.due)}</p></td><td>${B(stage==='已发布'?'查看复盘':stage==='待审核'?'去审核':'打开','select-task','quiet',`data-index="${i}"`)}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">没有符合条件的内容，请调整筛选。</div>'}</div><p class="mock-note">${rows.length} 条内容 · 全部为模拟数据；发布与效果指标仅用于演示。</p>`}
function content(){if(!S.contentDetail)return contentViews()+((S.contentView||'内容列表')==='发布日历'?publishCalendar():contentList());const t=tasks[S.task],m=contentInfo(S.task);const dv=versionStore[S.task+'-抖音']||{version:2,approved:false}, xv=versionStore[S.task+'-小红书']||{version:1,approved:S.task===0};let body;if(S.contentTab==='平台版本'){body=`<h3>平台版本（2）</h3><div class="version-cards">${B('<strong>'+I('play')+' 抖音视频 V'+dv.version+'</strong>'+badge(dv.approved?'已通过':'待重新审核',dv.approved?'green':'amber'),'platform',`version-card ${S.platform==='抖音'?'active':''}`,'data-platform="抖音"')}${B('<strong>'+I('file')+' 小红书图文 V'+xv.version+'</strong>'+badge(xv.approved?'已通过':'待重新审核',xv.approved?'green':'amber'),'platform',`version-card ${S.platform==='小红书'?'active':''}`,'data-platform="小红书"')}</div><div class="video-form">${S.platform==='抖音'?video():`<div class="box"><h3>${esc(S.title)}</h3><p>${esc(m.point)}</p><p class="muted">面向：${esc(m.audience)}</p><div class="spacer"></div>${badge('小红书图文 · V'+S.version)}</div>`}<div><label><span>标题 <span class="error-note">*</span></span><div class="count-field"><input id="version-title" value="${esc(S.title)}" maxlength="80" aria-label="平台版本标题"><small>${S.title.length}/80</small></div></label><label><span>字幕摘要</span><div class="count-field"><textarea id="version-subtitle" rows="4" aria-label="字幕摘要">${esc(S.subtitle)}</textarea><small>${S.subtitle.length}/200</small></div></label></div></div><div class="version-actions"><div class="notice">${I('info')} ${S.platform==='抖音'?`本次修改：标题与第2段字幕已调整；基于V1修改；原审核不适用于V${S.version}。`:'当前展示小红书图文 V'+S.version+'；修改实质内容后须重新审核。'}</div>${B('查看修改对比','compare')}${B('退回修改','return-edit')}${B(S.approved?'已审核通过':'审核通过V'+S.version,'approve','primary',S.approved?'disabled':'')}</div>`}else if(S.contentTab==='脚本'){body=`<h3>脚本编辑</h3><div class="spacer"></div>${['开场','核心观点','结尾引导'].map((s,i)=>`<label><span>${s}</span><textarea rows="3" id="script-${i}">${esc(S.scripts?.[S.task]?.[i]||[t[0],m.point,'如需进一步沟通，请先说明你的需求，再由律师确认服务范围。'][i])}</textarea></label>`).join('')}${B('确认脚本，进入制作','base-content','primary')}`}else if(S.contentTab==='观点与素材'){body=`<h3>采集你的专业观点</h3><p class="muted">这条内容最想帮助客户理解什么？</p><div class="spacer"></div><textarea id="opinion" rows="6" placeholder="补充真实经验、常见误区和需要说明的边界…">${esc(S.opinions?.[S.task]||m.point)}</textarea><div class="spacer"></div>${B('保存观点，生成脚本','save-opinion','primary')}<div class="spacer"></div><div class="box">${I('settings')} 已关联：${esc(m.service)}服务档案；来源：${esc(m.source)}。</div>`}else{body=`<div class="grid two">${video()}<div><h3>基础成品</h3><p>关联脚本已确认，已准备视频与图文内容。</p><div class="notice">${I('info')} 制作与生成结果均为 Mock，不调用真实 AI 服务。</div><div class="spacer"></div>${B('生成平台适配版本','content-tab','primary','data-tab="平台版本"')}</div></div>`}return `<div class="content-detail"><div class="detail-back">${B(I('back')+' 返回内容列表','content-list','quiet')}</div><div class="page-intro"><div><h2>${esc(t[0])}</h2><p class="muted">${esc(m.service)} · ${t[1]} · ${contentStage(S.task)}</p></div></div><details class="content-brief" open><summary>创作任务说明</summary><div class="brief-fields"><div><span>内容目标</span><strong>${esc(m.goal)}</strong></div><div><span>目标客户</span><strong>${esc(m.audience)}</strong></div><div><span>选题依据</span><strong>${esc(m.source)} · Mock</strong></div><div><span>协作与时间</span><strong>${esc(m.owner)} · ${esc(m.due)}</strong></div></div><p><b>核心观点：</b>${esc(m.point)}</p>${m.brief?`${m.brief.themeId?B('返回需求主题与选题依据','market-origin','quiet',`data-id="${m.brief.themeId}"`):''}<p><b>开场钩子：</b>${esc(m.brief.hook)}</p><p><b>画面素材：</b>${esc(m.brief.visual)}</p><p><b>专业边界：</b>${esc(m.brief.boundary)}</p><p><b>复盘指标：</b>${esc(m.brief.metric)}</p>`:''}<p class="muted">下一步：${esc(m.next)}。专业判断与对外表述需由达人确认。</p></details>${m.result?`<section class="content-results"><h3>发布复盘 · 模拟数据</h3><div class="content-overview"><span>播放量 <strong>${m.result.views}</strong></span><span>咨询 <strong>${m.result.consults}</strong></span><span>匹配客户 <strong>${m.result.matched}</strong></span><span>预约 <strong>${m.result.appointments}</strong></span></div><p class="muted">两平台合计，统计截至11月17日。${m.result.matched>1?'建议延伸客户高频咨询问题，准备后续问答。':'有咨询但匹配客户较少，建议细化目标人群与服务说明。'}</p></section>`:''}<section class="panel version-panel"><div class="tabs content-steps">${['观点与素材','脚本','基础成品','平台版本'].map((t,i)=>B(`<span class="step-number">${i+1}</span> ${t==='平台版本'?'审核与发布':t}`,'content-tab',t===S.contentTab?'active':'',`data-tab="${t}"`)).join('')}</div><div class="version-body">${body}</div></section>${S.contentTab==='平台版本'?publishingPanel()+`<div class="review-footer"><span class="muted">审核仅针对当前平台版本，修改后须重新确认。</span></div>`:''}</div>`}

const inboxRecords=[
 ['A','抖音','私信','高意向','婚前财产规划','我在上海，希望本周线上聊一下，怎么预约？','明确咨询时间并主动询问预约方式',true],
 ['B','小红书','私信','高意向','复杂离婚诉讼代理','我想约一次咨询，涉及房产和股权，能安排吗？','有具体复杂事项，主动提出咨询预约意愿',true],
 ['C','抖音','评论','待识别','婚前财产规划','婚前协议一般需要先了解哪些信息？','尚未表达具体服务需求',false],
 ['D','小红书','评论','一般','婚姻法律咨询','第一次咨询，需要准备什么？','询问通用流程，尚无预约意愿',false],
 ['E','视频号','私信','待识别','婚姻法律咨询','我想了解线上咨询流程。','待补充城市与具体诉求',false],
 ['F','小红书','私信','一般','婚前财产规划','暂时不着急，只想先了解一下。','目前为信息了解阶段',false],
 ['G','抖音','评论','待识别','婚姻法律咨询','在哪里可以看咨询流程？','询问流程，不收集公开隐私',false],
 ['H','视频号','评论','一般','婚姻法律咨询','具体问题可以在评论里说吗？','引导通过原平台私信沟通',false]
].map(([id,platform,channel,intent,service,text,reason,alert])=>({id,platform,channel,intent,service,reason,alert,pending:['C','E'].includes(id),messages:[{who:'customer',text,time:'10:24'},...(!['C','E'].includes(id)?[{who:'agent',text:alert?'已记录您的需求，我会请律师确认服务范围与可预约时间，请稍候。':channel==='评论'?'咨询流程可通过本账号私信了解，评论区请勿留下个人材料。':'可以先了解服务流程，确定具体需求后再由律师确认安排。',time:'10:25'}]:[])]}));
function receptionState(q){if(q.waitingResponse&&!S.manual[q.id])return '等待客户回应';return S.manual[q.id]?'人工接待':q.alert?'待人工接手':q.pending?'Agent 待回复':'Agent 接待中'}
function customerConversations(c){return inboxRecords.filter(q=>S.clientLinks?.[q.id]===c.id)}
function linkedCustomer(q){return clients.find(c=>c.id===S.clientLinks?.[q.id])}
function syncLead(q,create=false){let c=linkedCustomer(q);if(!c&&create){c={id:'线索'+(clients.length+1),source:q.platform,service:q.service,stage:'待确认',next:'确认服务匹配并接手沟通',due:'今天内',appointment:'',appointmentStatus:'未预约',history:[],taskDone:false,owner:'未分配',city:'待确认',timeframe:'待确认',budget:'待沟通',contact:'原平台沟通',match:'待确认'};clients.push(c);(S.clientLinks??={})[q.id]=c.id;S.linked.add(q.id);c.history.push('Agent 识别需求并建立待确认线索：'+q.platform+' / '+q.channel)}if(c){const high=customerConversations(c).filter(r=>r.intent==='高意向');c.intent=high.length?'高意向':q.intent;c.intentReason=high.length?high.map(r=>r.platform+'：'+r.reason).join('；'):q.reason;c.agentSummary=q.messages.filter(m=>m.who==='customer').at(-1)?.text||'';if(!c.summaryEdited)c.summary=c.agentSummary;c.lastInteraction='刚刚';}return c}
// These seed identities are explicitly linked mock records, not name-based matching.
S.clientLinks={A:'A',B:'B',D:'D'};for(const id of ['A','B','D']){S.linked.add(id);const q=inboxRecords.find(q=>q.id===id);syncLead(q);const c=linkedCustomer(q);c.source=q.platform;c.service=q.service;c.city=id==='A'?'上海':'待确认';c.owner=id==='B'?'未分配':'林律师';c.match=id==='D'?'已确认':'初步匹配';c.timeframe=id==='A'?'本周':'待确认';c.budget='待沟通';c.contact='原平台'+q.channel;c.history.push(id==='B'?'Agent 识别高意向，生成待确认线索':'已确认关联原平台会话（模拟）')}
Object.assign(clients.find(c=>c.id==='B'),{stage:'待确认',next:'确认服务匹配并接手沟通',due:'今天内'});
function matchesLeadFocus(c){const f=S.leadFocus||'全部';return f==='全部'||f==='待确认'&&c.stage==='待确认'||f==='高意向'&&c.intent==='高意向'||f==='待接手'&&customerConversations(c).some(q=>q.alert&&!S.manual[q.id])||f==='已预约'&&c.appointmentStatus==='已预约'||f==='今日跟进'&&!c.taskDone&&(c.due?.includes('11月17')||c.due?.includes('2026-11-17')||c.due==='今天内')}
function leadHandoff(c){const origins=customerConversations(c);return `<section class="lead-handoff"><div class="row between"><h3>接待交接</h3>${B('完善客户资料','lead-profile','quiet')}</div><p>${esc(c.summary||'尚未整理客户需求，请补充首次沟通情况。')}</p><div class="handoff-facts"><div><span>客户意向</span><strong>${esc(c.intent||'待识别')}</strong></div><div><span>服务匹配</span><strong>${esc(c.match||'待确认')}</strong></div><div><span>负责人</span><strong>${esc(c.owner||'未分配')}</strong></div><div><span>期望时间</span><strong>${esc(c.timeframe||'待确认')}</strong></div></div><p class="muted">意向依据：${esc(c.intentReason||'暂无接待判断')}</p><p class="muted">城市：${esc(c.city||'待确认')} · 预算：${esc(c.budget||'待沟通')} · 沟通方式：${esc(c.contact||'待确认')}</p><details><summary>查看关联会话（${origins.length}）与客户原话</summary>${origins.map(q=>`<div class="origin-record"><div class="row between"><strong>${q.platform} · ${q.channel} · 客户${q.id}</strong>${B(S.manual[q.id]?'继续回复':q.alert?'接手回复':'打开会话','origin-conversation','quiet',`data-origin="${q.id}"`)}</div><p class="muted">${receptionState(q)}</p><p>“${esc(q.messages.filter(m=>m.who==='customer').at(-1)?.text||'')}”</p></div>`).join('')||'<p class="muted">暂无关联会话，手动线索可先补充跟进记录。</p>'}</details>${c.stage==='待确认'?`<div class="lead-decision"><p>确认承接后进入待跟进；不适合的需求可记录原因并关闭。</p><div class="row">${B('确认承接','accept-lead','primary')}${B('不适合承接','decline-lead')}</div></div>`:''}</section>`}
function processAgent(q){if(S.manual[q.id]||q.alert||!q.pending)return;if(!serviceActive(q.service)||/价格|多少钱|费用|收费/.test(q.messages.at(-1)?.text||'')){q.messages.push({who:'agent',time:'刚刚',text:priceReply(q.service)});q.pending=false;return;}const high=/预约|约一次|本周.*咨询|付费/.test(q.messages.at(-1)?.text||'');if(high){q.intent='高意向';q.reason='最新消息主动提出咨询时间或预约需求';q.alert=true}q.messages.push({who:'agent',time:'刚刚',text:high?'已记录您的咨询意愿，接下来由律师确认服务范围和预约时间。':q.channel==='评论'?'可以通过本账号私信说明需求，评论区请不要提供个人材料。':'为了确认是否适合接待，请先说明服务城市与希望解决的问题。'});q.pending=false;syncLead(q,high)}
function reception(){const platform=S.inboxPlatform||'全部平台';const visible=inboxRecords.filter(q=>(platform==='全部平台'||q.platform===platform)&&(S.inbox==='全部'||S.inbox==='高意向'&&q.intent==='高意向'||S.inbox==='待接手'&&q.alert&&!S.manual[q.id]||S.inbox==='人工接待'&&S.manual[q.id]||S.inbox==='Agent接待'&&!S.manual[q.id]&&!q.alert));if(!visible.some(q=>q.id===S.conversation)&&visible.length)S.conversation=visible[0].id;const q=visible.find(q=>q.id===S.conversation),alerts=inboxRecords.filter(q=>q.alert&&!S.manual[q.id]).length;const summary=`<div class="page-intro"><div><h2>多平台统一接待</h2><p class="muted">Agent 默认处理评论与私信；高意向提醒后暂停自动回复，等待人工接手。</p></div>${B('接待规则','reception-settings')}</div><div class="reception-summary"><span>Agent 已回复 <strong>${inboxRecords.reduce((n,q)=>n+q.messages.filter(m=>m.who==='agent').length,0)}</strong></span><span>Agent 待回复 <strong>${inboxRecords.filter(q=>q.pending&&!q.alert&&!S.manual[q.id]).length}</strong></span><span>高意向 <strong>${inboxRecords.filter(q=>q.intent==='高意向').length}</strong></span><span>待人工接手 <strong>${alerts}</strong></span>${alerts?B('查看待接手 '+alerts+' 位','inbox-filter','quiet','data-filter="待接手"'):''}</div><div class="inbox-toolbar"><select id="inbox-platform" aria-label="来源平台">${['全部平台','抖音','小红书','视频号'].map(p=>`<option value="${p}" ${p===platform?'selected':''}>${p}</option>`).join('')}</select><div class="pills">${['全部','Agent接待','高意向','待接手','人工接待'].map(t=>B(t,'inbox-filter',S.inbox===t?'active':'',`data-filter="${t}"`)).join('')}</div></div>`;if(!q)return summary+'<div class="panel empty">该筛选下暂无会话，请切换平台或接待状态。</div>';const manual=!!S.manual[q.id],linked=S.linked.has(q.id),lead=linkedCustomer(q),facts=S.facts?.[q.id]||{};if(lead)S.customer=lead.id;return summary+`<div class="reception-grid unified-inbox"><section class="panel"><p class="muted inbox-count">${visible.length} 个会话 · 按平台身份区分</p>${visible.map(r=>B(`<span class="user-avatar">${I('user')}</span><span class="contact-copy"><span class="row between"><strong>客户${r.id}</strong>${r.alert&&!S.manual[r.id]?'<span class="handoff-dot" aria-label="待接手提醒"></span>':''}</span>${platformMark(r.platform,r.channel)}<p>${esc(r.messages.filter(m=>m.who==='customer').at(-1).text)}</p><span class="contact-state">${receptionState(r)}${r.intent==='高意向'?' · 高意向':''}</span></span>`,'select-conversation',`contact-row ${q.id===r.id?'active':''}`,`data-id="${r.id}"`)).join('')}</section><section class="panel"><div class="chat-head"><div class="row between"><h2>客户${q.id}</h2>${badge(receptionState(q),q.alert?'amber':'')}</div><p class="source-heading">${platformMark(q.platform,q.channel)}<span class="muted"> · 回复将回到原平台${q.channel==='评论'?'评论区':'私信'}</span></p></div>${q.alert&&!manual?`<div class="handoff-banner"><div><strong>高意向客户，等待你接手</strong><p>${esc(q.reason)}。Agent 已告知客户等待律师确认。</p></div>${B('接手回复','takeover','primary')}</div>`:''}<div class="chat-body">${q.messages.map(m=>`<div class="chat-message ${m.who==='customer'?'':'reply'}"><span class="user-avatar">${I(m.who==='agent'?'agent':'user')}</span><div><div class="chat-meta">${m.who==='customer'?'客户'+q.id:m.who==='agent'?'接待 Agent':'林律师（人工）'} · ${m.time}</div><div class="bubble">${esc(m.text)}</div></div></div>`).join('')}</div>${manual?`<form id="reply-form" class="composer"><textarea name="reply" placeholder="回复至${q.platform}${q.channel}…" aria-label="回复内容" required></textarea><button class="primary">发送回复</button></form><div class="row between reception-control"><span class="muted">人工接待期间，Agent 已暂停。</span>${B('交回 Agent','resume-agent','quiet')}</div>`:`<div class="agent-composer"><p>${q.waitingResponse?'已完成主动回复，等待客户回应。':q.alert?'等待人工接手，Agent 不再继续回复。':q.pending?'Agent 正在等待处理这条消息。':'当前由 Agent 接待，无需逐条确认回复。'}</p><div class="row wrap">${!q.alert?B('人工接手','takeover'):''}${q.pending&&!q.alert?B('模拟 Agent 回复','simulate-agent','quiet'):''}${!q.alert?B('模拟一条预约消息','simulate-message','quiet'):''}</div></div>`}<p class="mock-note">演示模式：仅更新本地会话，不会向平台发送消息。</p></section><section class="panel client-understanding"><h2>客户意向</h2>${badge(q.intent,q.intent==='高意向'?'amber':'')}<p>${esc(q.reason)}</p><div class="inbox-fact"><span>关联服务</span><strong>${esc(facts.service||lead?.service||q.service)}</strong></div><div class="inbox-fact"><span>来源身份</span><strong>${q.platform} / 客户${q.id}</strong><p class="muted">不同平台的同名用户不自动合并。</p></div><details class="customer-disclosure"><summary>需求判断与客户档案</summary><p>服务匹配：${esc(facts.match||(q.intent==='高意向'?'初步匹配':'待确认'))}</p><p>待补信息：本人咨询、城市、材料准备情况。</p>${B('调整需求判断','edit-fact','quiet','data-field="服务匹配"')}<div class="spacer"></div><p>${linked?'已关联客户 '+esc(S.clientLinks?.[q.id]||q.id):'尚未关联客户档案'}</p>${B('搜索并关联已有客户','link-client','quiet')}</details>${B(linked?'查看客户档案':'确认并关联线索',linked?'open-current-client':'convert','wide')}${lead?`<div class="inbox-fact"><span>线索进度 · ${esc(lead.stage)}</span><p>负责人：${esc(lead.owner||'未分配')}</p><p>预约：${esc(lead.appointmentStatus)}${lead.appointment?' · '+esc(lead.appointment.replace('T',' ')):''}</p><p>下一步：${lead.taskDone?'已完成':esc(lead.next)}</p><div class="customer-quick-actions">${lead.stage==='待确认'?B('确认承接','accept-lead'):B(lead.appointment?'调整预约':'安排预约','appointment')}${B('新建跟进任务','new-task')}</div></div>`:'<p class="muted">高意向自动生成待确认线索；一般咨询按需建档。</p>'}</section></div>`}
function leads(){const c=clients.find(x=>x.id===S.customer)||clients[0],rows=clients.filter(x=>matchesLeadFocus(x)&&(S.clientFilter==='全部'||x.stage===S.clientFilter)&&(S.source==='全部来源'||x.source===S.source||customerConversations(x).some(q=>q.platform===S.source))&&(!S.search||('客户'+x.id+x.service).includes(S.search)));return `<div class="page-intro"><div><h2>客户跟进</h2><p class="muted">从接待中承接需求，统一处理预约、下一步跟进与转化结果。</p></div>${B('查看咨询接待','goto-reception')}</div><div class="lead-focus">${['全部','待确认','高意向','待接手','今日跟进','已预约'].map(t=>B(t,'lead-focus',(!S.leadFocus&&t==='全部'||S.leadFocus===t)?'active':'',`data-filter="${t}"`)).join('')}</div><div class="crm-grid"><section class="panel crm-list"><h2>客户线索 <small class="muted">（共 ${clients.length} 个）</small></h2><div class="pills">${['全部','待确认','待跟进','沟通中','已委托','已关闭'].map(t=>B(t+' '+clients.filter(x=>t==='全部'||x.stage===t).length,'client-filter',S.clientFilter===t?'active':'',`data-filter="${t}"`)).join('')}</div><form id="client-search" class="crm-search"><input name="search" value="${esc(S.search)}" placeholder="搜索客户或服务需求" aria-label="搜索客户"><span>线索来源</span><select id="client-source" aria-label="线索来源">${['全部来源','抖音','小红书','微信公众号','视频号','知乎'].map(t=>`<option ${t===S.source?'selected':''}>${t}</option>`).join('')}</select>${B(I('plus')+' 新增线索','new-client','primary')}<button hidden>搜索</button></form><table class="crm-table"><thead><tr><th>客户</th><th>服务 / 意向</th><th>客户阶段</th><th>下一步 / 时间</th><th>负责人</th></tr></thead><tbody>${rows.map(x=>`<tr class="${S.clientOpen&&x.id===c.id?'selected':''}" data-action="select-client" data-id="${x.id}" tabindex="0" aria-label="查看客户${x.id}"><td><span class="customer-name"><span class="user-avatar">${I('user')}</span><span><strong>客户${x.id}</strong><small>${esc(x.source)}</small></span></span></td><td>${esc(x.service)}<p class="muted">${esc(x.intent||'待识别')}${customerConversations(x).some(q=>q.alert&&!S.manual[q.id])?' · 待接手':''}</p></td><td>${badge('● '+x.stage,x.stage==='待跟进'?'amber':x.stage==='已关闭'?'gray':'green')}</td><td>${x.taskDone?'已完成':esc(x.next)}<p class="muted">${esc(x.due)}</p></td><td>${esc(x.owner||'未分配')}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">没有符合条件的客户</div>'}</section></div>${S.clientOpen?`<dialog id="client-drawer" class="client-drawer" aria-label="客户档案"><section class="crm-detail"><div class="panel-head"><h2>客户${esc(c.id)}</h2>${B(I('close'),'close-client','icon-button','aria-label="关闭客户档案"')}${B(I('message')+' 查看接待记录','client-conversation')}</div>${leadHandoff(c)}<div class="state-cards"><div class="state-card">${I('user')}客户阶段<strong>${c.stage}</strong></div><div class="state-card">${I('calendar')}预约状态<strong>${c.appointmentStatus}</strong></div><div class="state-card">${I('clock')}下一项任务<strong>${c.taskDone?'已完成':esc(c.next==='—'?'暂无任务':c.next.replace('明天',''))}</strong></div></div><div class="appointment-box"><div class="row between"><strong>${I('calendar')} ${c.appointment?'预约咨询：'+c.appointment.replace('T',' ')+'　线上咨询':'尚未安排预约'}</strong><div class="row">${B(c.appointment?'修改预约':'安排预约','appointment')}${c.appointment?B('取消预约','cancel-appointment')+B('记录咨询结果','consult-result'):''}</div></div><div class="notice">${I('info')} 取消预约不会关闭客户，仍可继续沟通并重新预约。</div></div><div class="compact-facts"><div>${I('file')}<strong>需求摘要</strong><span>${esc(c.summary||c.service+'相关咨询，待补充具体需求')}</span></div><div>${I('link')}<strong>线索来源</strong><span>${esc(c.source)} · ${customerConversations(c).length?'来源会话已关联':'手动录入 / 待关联'}</span></div></div>${panel('跟进记录',`<div class="timeline">${c.history.length?'':'<p class="muted">暂无跟进记录</p>'}${c.history.map(h=>`<div class="timeline-item"><strong>刚刚</strong><p>${esc(h)}</p></div>`).join('')}</div>`)}<div class="next-task"><div class="row">${I('clock')}下一项任务</div><div class="row between"><strong>${esc(c.next)}</strong>${B(c.taskDone?'已完成':'标记完成','complete-task',c.taskDone?'quiet':'',c.taskDone?'disabled':'')}</div><p class="muted">截止时间：${esc(c.due||'未设置')}</p></div><div class="crm-actions">${B(I('plus')+' 添加跟进','followup','primary')}${B(I('review')+' 新建任务','new-task')}${B(I('check')+' 记录结果','outcome')}</div></section></dialog>`:''}`}
function publishCalendar(){const start=new Date(Date.UTC(2026,10,16+(S.calendarWeek||0)*7));const dates=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setUTCDate(start.getUTCDate()+i);return d.toISOString().slice(0,10)});const selected=S.calendarStatus||'全部';const matches=p=>selected==='全部'||(selected==='待重新审核'?p.status.includes('暂停'):p.status===selected);const unscheduled=S.posts.filter(p=>p.status.includes('暂停')||p.status==='发布失败');return `<div class="page-intro"><div><h2>发布日历</h2><p class="muted">按平台查看排期，点击任务进入对应内容版本。</p></div><div class="row">${B('上一周','calendar-prev')}${B('本周','calendar-today')}${B('下一周','calendar-next')}</div></div><div class="row between calendar-heading"><strong>${dates[0]} — ${dates[6]}</strong><select id="calendar-status" aria-label="发布状态">${['全部','已排期','已发布','发布失败','待重新审核'].map(t=>`<option value="${t}" ${t===selected?'selected':''}>${t}</option>`).join('')}</select></div><div class="publish-calendar">${dates.map((date,i)=>`<section class="calendar-day"><h3>${['周一','周二','周三','周四','周五','周六','周日'][i]} <span>${date.slice(5)}</span></h3>${S.posts.filter(p=>p.at.startsWith(date)&&matches(p)).map(p=>B(`<span class="muted">${p.at.slice(11)} · ${p.platform}</span><strong>${esc(p.title)}</strong><span>${esc(p.status)}</span>`,'post-detail','calendar-post',`data-index="${S.posts.indexOf(p)}"`)).join('')||'<p class="calendar-empty">暂无任务</p>'}</section>`).join('')}</div>${unscheduled.length?`<section class="panel calendar-attention"><h3>需要处理 · ${unscheduled.length}</h3>${unscheduled.map(p=>`<div class="row between"><div><p>${esc(p.title)}</p><p class="muted">${p.platform} · ${esc(p.error||p.status)}</p></div>${B('查看并处理','post-detail','quiet',`data-index="${S.posts.indexOf(p)}"`)}</div>`).join('')}</section>`:''}<p class="mock-note">全部为模拟排期；时间到达不会触发真实发布。</p>`}
// Historical mock cohort is separate from the current-day interactive CRM demo.
const analysisContent=[
 {title:'婚姻家事热点问答合集',kind:'热点科普',goal:'触达客户',task:null,views:96000,visits:760,n:14,matched:3,accepted:2,booked:1,completed:1,won:0},
 {title:tasks[3][0],kind:'普法科普',goal:'建立信任',task:3,views:24360,visits:490,n:10,matched:8,accepted:6,booked:4,completed:3,won:1},
 {title:'复杂财产咨询：先整理什么材料',kind:'咨询准备',goal:'筛选匹配客户',task:null,views:6200,visits:260,n:8,matched:6,accepted:5,booked:4,completed:2,won:1},
 {title:tasks[11][0],kind:'咨询准备',goal:'推动预约',task:11,views:8740,visits:180,n:4,matched:3,accepted:3,booked:3,completed:1,won:0}
];
const analysisRows=analysisContent.flatMap((c,ci)=>Array.from({length:c.n},(_,j)=>{const matched=j<c.matched,accepted=j<c.accepted,booked=j<c.booked,completed=j<c.completed,won=j<c.won;return {id:'历史客户 '+(ci+1)+'-'+(j+1),date:'2026-11-'+String(ci===1?16:ci===3?15+j%2:2+(j+ci*3)%15).padStart(2,'0'),content:ci,platform:['抖音','小红书','视频号'][j%3],entry:j%3===0?'评论':'私信',service:['婚姻法律咨询','婚前财产规划','复杂离婚诉讼代理','婚姻法律咨询'][ci],high:j%3!==2,matched,accepted,booked,completed,won,region:j%5!==4,clear:j%4!==3,reason:!matched?['服务范围不符','服务地区不符','需求尚不明确'][j%3]:!accepted?'材料或授权待确认':!booked?'等待确认咨询时间':!completed?(j%2?'客户取消':'未到场'):!won?'仍在比较方案':'已委托',agentReply:j%7!==6,response:20+j*13,handoff:j%3!==2,handoffMinutes:8+j*19,corrected:j%9===4,followupLate:accepted&&j%3===2,attribution:j%6===5?'来源未知':j%4===3?'客户自述':'平台关联',note:'历史模拟样本，仅用于演示分析口径。'}}));
function analysisFilter(rows=analysisRows){return rows.filter(r=>(S.analysisPeriod!=='近7天'||r.date>='2026-11-10')&&(!S.analysisPlatform||S.analysisPlatform==='全部平台'||r.platform===S.analysisPlatform)&&(!S.analysisService||S.analysisService==='全部服务'||r.service===S.analysisService))}
const rate=(n,d)=>d?Math.round(n/d*100)+'%':'—';
function analysisTable(headers,rows){return `<div class="analysis-table"><table class="full-table"><thead><tr>${headers.map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(t=>`<td>${t}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function analysisKpis(items){return `<div class="analysis-kpis">${items.map(([title,value,sub])=>`<div><span>${title}</span><strong>${value}</strong><small>${sub}</small></div>`).join('')}</div>`}
function analysisCohort(type,index){const rows=analysisFilter().filter(r=>type==='content'?r.content===Number(index)&&r.attribution!=='来源未知':type==='platform'?r.platform===index:type==='service'?r.service===index:!index||r[index]);modal('历史样本明细 · Mock',`<p class="muted">与当前接待台分开保存的演示快照；不代表当前待办。</p>${analysisTable(['客户 / 日期','来源','服务','进展'],rows.map(r=>[esc(r.id)+'<p class="muted">'+r.date+'</p>',esc(r.platform+' · '+r.entry),esc(r.service),esc(r.reason)]))}`)}
function analytics(){const rows=analysisFilter(),n=rows.length,count=k=>rows.filter(r=>r[k]).length,tab=S.analysisTab||'获客总览',matched=count('matched'),accepted=count('accepted'),booked=count('booked'),completed=count('completed'),won=count('won');const sources=['抖音','小红书','视频号'];let body='';if(tab==='获客总览'){const funnel=[['新增咨询',n,''],['服务匹配',matched,'matched'],['确认承接',accepted,'accepted'],['已预约',booked,'booked'],['完成咨询',completed,'completed'],['已委托',won,'won']];body=analysisKpis([['服务匹配客户',matched,rate(matched,n)+' · '+matched+'/'+n+' 位咨询客户'],['完成咨询',completed,rate(completed,booked)+' · '+completed+'/'+booked+' 位预约客户'],['新增委托',won,rate(won,completed)+' · '+won+'/'+completed+' 位完成咨询客户'],['高意向客户',count('high'),'与服务匹配分别判断']])+`<div class="analysis-two">${panel('获客转化路径',`<div class="analysis-funnel">${funnel.map(([label,value,key],i)=>`<div><div class="row between"><strong>${label}</strong>${B(value+' 人','analysis-cohort','quiet',`data-kind="funnel" data-index="${key}"`)}</div><div class="analysis-track"><span style="width:${n?value/n*100:0}%"></span></div><p class="muted">${i?'上一步转化 '+rate(value,funnel[i-1][1])+'（'+value+'/'+funnel[i-1][1]+'）':'按客户去重，同一批历史样本'}</p></div>`).join('')}</div>`)}${panel('客户质量',analysisTable(['判断','人数 / 分母','占比'],[['高意向且匹配',rows.filter(r=>r.high&&r.matched).length+' / '+n,rate(rows.filter(r=>r.high&&r.matched).length,n)],['高意向但不匹配',rows.filter(r=>r.high&&!r.matched).length+' / '+count('high'),rate(rows.filter(r=>r.high&&!r.matched).length,count('high'))],['服务地区适合',count('region')+' / '+n,rate(count('region'),n)],['需求表达明确',count('clear')+' / '+n,rate(count('clear'),n)]])+`<p class="muted">意向强不代表适合承接；优先确认服务范围、地区与材料条件。</p>`)}</div>${panel('尚未转化的原因',analysisTable(['当前停留原因','客户数','建议关注'],['服务范围不符','服务地区不符','需求尚不明确','材料或授权待确认','等待确认咨询时间','客户取消','未到场','仍在比较方案'].map(reason=>[reason,rows.filter(r=>r.reason===reason).length,reason==='等待确认咨询时间'?'缩短人工接手与时间确认等待':reason==='服务范围不符'?'优化选题与服务说明':'结合客户原话核实原因'])))}${panel('达人投入 · 模拟工作记录',`<p>所选样本涉及 ${new Set(rows.map(r=>r.content)).size} 项历史内容。每项模拟记录：审核 2 轮、达人投入 25 分钟。</p><p class="muted">合计 ${new Set(rows.map(r=>r.content)).size*25} 分钟；没有人工基线，暂不宣称节省了多少时间。</p>`)}`}else if(tab==='渠道与内容'){body=panel('平台获客质量',analysisTable(['平台','咨询','高意向','匹配','预约','完成 / 委托','明细'],sources.map(p=>{const rs=rows.filter(r=>r.platform===p),c=k=>rs.filter(r=>r[k]).length;return [p,rs.length,c('high'),c('matched')+' · '+rate(c('matched'),rs.length),c('booked'),c('completed')+' / '+c('won'),B('查看客户','analysis-cohort','quiet',`data-kind="platform" data-index="${p}"`)]})))+panel('内容贡献',analysisTable(['内容 / 栏目','咨询 / 匹配','预约 / 委托','来源证据','明细'],analysisContent.map((c,i)=>{const rs=rows.filter(r=>r.content===i&&r.attribution!=='来源未知');return [esc(c.title)+'<p class="muted">'+c.kind+' · '+c.goal+'</p>',rs.length+' / '+rs.filter(r=>r.matched).length,rs.filter(r=>r.booked).length+' / '+rs.filter(r=>r.won).length,rs.filter(r=>r.attribution==='平台关联').length+' 平台关联 · '+rs.filter(r=>r.attribution==='客户自述').length+' 自述 · '+rs.filter(r=>r.attribution==='来源未知').length+' 未知',B('客户明细','analysis-cohort','quiet',`data-kind="content" data-index="${i}"`)+(c.task!==null?' '+B('查看内容','analysis-content','quiet',`data-index="${c.task}"`):'')]})))+panel('内容传播参考 · 独立全量快照',analysisTable(['内容','播放 / 阅读次数','主页访问次数'],analysisContent.map(c=>[esc(c.title),c.views.toLocaleString(),c.visits]))+'<p class="muted">11月1—16日的跨平台全量演示数据，不随上方客户筛选变化，不与客户数直接相除计算转化。平台曝光口径不同，访问次数不等于独立客户数。</p>')+panel('服务需求与转化',analysisTable(['服务','咨询','匹配 / 承接','预约 / 完成','委托','明细'],S.services.map(service=>{const rs=rows.filter(r=>r.service===service),c=k=>rs.filter(r=>r[k]).length;return [service,rs.length,c('matched')+' / '+c('accepted'),c('booked')+' / '+c('completed'),c('won'),B('查看客户','analysis-cohort','quiet',`data-kind="service" data-index="${service}"`)]})))+panel('来源归因说明',`<p>当前筛选中有 ${rows.filter(r=>r.attribution==='来源未知').length} 位客户来源未知，计入总览及平台统计，不计入上方具体内容贡献。</p><p>首次触点、触发咨询内容和客户自述是不同字段。本次按平台关联与客户自述展示贡献，无法确认的来源保留“未知”。未知来源不用于评判某条内容的成交贡献。</p>`)}else{const alerts=rows.filter(r=>r.handoff),replied=rows.filter(r=>r.agentReply);body=analysisKpis([['Agent 回复覆盖',rate(replied.length,n),replied.length+'/'+n+' 位咨询客户'],['平均首次响应',replied.length?Math.round(replied.reduce((v,r)=>v+r.response,0)/replied.length)+' 秒':'—','仅计算 Agent 已回复样本'],['人工接手超过30分钟',alerts.filter(r=>r.handoffMinutes>30).length,alerts.length+' 次转人工提醒中'],['预约完成率',rate(completed,booked),completed+'/'+booked+' 位预约客户']])+`<div class="analysis-two">${panel('Agent 接待质量',analysisTable(['指标','结果','口径'],[['高意向提醒',alerts.length,'触发转人工的客户数'],['达人纠正判断',count('corrected'),'人工修改意向或匹配判断'],['人工纠正比例',rate(count('corrected'),n),count('corrected')+'/'+n+'；不等于模型准确率'],['评论 / 私信入口',rows.filter(r=>r.entry==='评论').length+' / '+rows.filter(r=>r.entry==='私信').length,'按首次咨询入口分类']]))}${panel('人工跟进与预约',analysisTable(['指标','人数 / 分母','说明'],[['跟进逾期',count('followupLate')+' / '+accepted,'已承接客户中，任务未按时完成'],['预约未完成',(booked-completed)+' / '+booked,'包括取消和未到场'],['取消预约',rows.filter(r=>r.reason==='客户取消').length,'客户明确取消'],['未到场',rows.filter(r=>r.reason==='未到场').length,'预约结束后记录'],['完成咨询后未委托',(completed-won)+' / '+completed,'仍需了解决策障碍']]))}</div>${panel('转人工等待样本',analysisTable(['客户','来源','意向 / 匹配','提醒至接手','下一步'],alerts.slice(0,8).map(r=>[esc(r.id),r.platform,r.high?'高意向 / '+(r.matched?'匹配':'不匹配'):'待判断',r.handoffMinutes+' 分钟',r.handoffMinutes>30?'检查提醒与值班安排':'保持及时接手'])))}`}
const action=tab==='渠道与内容'?['调整选题与服务说明','高播放内容可能带来较多不匹配咨询，应结合匹配客户而非播放量选题。','查看账号策略','goto-strategy']:tab==='接待与转化'?['缩短高意向客户的接手等待','对超时接手与跟进逾期分别处理；先确认负责人，再安排下一次沟通。','处理当前待接手','analysis-handoff']:['优先补齐承接与预约之间的沟通','查看等待确认时间的原因，区分客户尚未决定与达人尚未回复。','查看当前客户跟进','analysis-followup'];return `<div class="analysis-toolbar"><select id="analysis-period" aria-label="统计周期">${['本月','近7天'].map(t=>`<option value="${t}" ${(S.analysisPeriod||'本月')===t?'selected':''}>${t}</option>`).join('')}</select><select id="analysis-platform" aria-label="分析平台">${['全部平台',...sources].map(t=>`<option value="${t}" ${(S.analysisPlatform||'全部平台')===t?'selected':''}>${t}</option>`).join('')}</select><select id="analysis-service" aria-label="分析服务">${['全部服务',...S.services].map(t=>`<option value="${t}" ${(S.analysisService||'全部服务')===t?'selected':''}>${t}</option>`).join('')}</select><span class="muted">${S.analysisPeriod==='近7天'?'11月10日—16日':'11月1日—16日'} · ${n} 位历史模拟客户</span></div><div class="tabs strategy-tabs">${['获客总览','渠道与内容','接待与转化'].map(t=>B(t,'analysis-tab',t===tab?'active':'',`data-tab="${t}"`)).join('')}</div><div class="analysis-body">${n?body:'<div class="panel empty">当前条件下暂无历史样本，请调整筛选。</div>'}${n?panel('下一步行动',`<div class="row between wrap"><div><h3>${action[0]}</h3><p class="muted">${action[1]}</p><p class="muted">历史分析建议；下方入口进入当前工作队列，数量可能不同。</p></div>${B(action[2],action[3],'primary')}</div>`):''}<details class="analysis-notes"><summary>统计口径与数据边界</summary><p>这是一批独立的历史 Mock 客户快照，当前接待和客户页中的演示操作不会改写历史报表。漏斗按同一批客户计算；高意向单独分析，不作为匹配的前置条件。比例均展示分子与分母，零分母记为“—”。</p><p>平台身份未确认时不自动跨平台去重。成交归因、金额、获客成本和节省时间缺乏依据时不作推断。当前没有接入真实平台或费用数据。</p></details></div>`}
