document.addEventListener('input',e=>{if(['version-title','version-subtitle'].includes(e.target.id)){invalidate();S[e.target.id==='version-title'?'title':'subtitle']=e.target.value;saveVersion();const count=e.target.parentElement.querySelector('small');if(count)count.textContent=e.target.value.length+'/'+(e.target.id==='version-title'?80:200);const b=$('[data-action="approve"]');b.disabled=false;b.textContent='审核通过V'+S.version;const card=$('[data-action="platform"][data-platform="'+S.platform+'"]');if(card){card.querySelector('strong').textContent=S.platform+' V'+S.version;const state=card.querySelector('.badge');state.textContent='待重新审核';state.className='badge amber';}const pub=$('.inline-publish');if(pub)pub.outerHTML=publishingPanel();} });
